$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.7.4"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version exact missing-row importer..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\central_zone_exact_import_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile `
  ".\mntrapteam\central_zone_exact_import_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.7.4 installed."
Write-Host "Writes only Central Zone rows proven missing from exact MyATA Score Details."
Write-Host ""
Write-Host "Next:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.central_zone_exact_import_cli write'
